OPENQASM 3.0;
    include "stdgates.inc";

    def my_function(qubit a, float[32] b) {
        rx(b) a;
        float[64] c = 2*b;
        rx(c) a;
        return;
    }
    qubit q;
    float[32] r = 3.14;
    my_function(q, r);

OPENQASM 3.0;
    include "stdgates.inc";

    def my_function(qubit q) {
        float[32] a = 3.14;
        a = 2*a;
        rx(a) q;
        return;
    }
    qubit q;
    my_function(q);

OPENQASM 3.0;
    include "stdgates.inc";

    def my_function(qubit q) -> float[32] {
        h q;
        return 3.14;
    }
    qubit q;
    float[32] r = my_function(q);

OPENQASM 3.0;
    include "stdgates.inc";
    def my_function(qubit q1, float[32] a) {
        h q1;
        rx(a) q1;
        return;
    }

    def my_function_2(qubit[2] q2, float[32] param) {
        my_function(q2[1], param);
        return;
    }

    def my_function_3(qubit[2] q3) {
        float[32] a = 3.14;
        my_function_2(q3, a);
        my_function(q3[1], a);
        return;
    }

    qubit[2] q;
    float[32] r = 3.14;
    my_function_2(q, r);
    my_function_3(q);
